SELECT 
FROM expense_claims ec
LEFT JOIN employees e ON e.id = ec.employee_id
LEFT JOIN departments d ON d.id = e.department_id
LEFT JOIN employees mgr ON mgr.id = ec.manager_id
WHERE ec.company_id = #{companyId}

    AND ec.status = #{status}


    AND ec.category = #{category}

ORDER BY ec.id DESC

